import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;
import java.util.*;

public class CashierDashboard extends JFrame {
    User user; DefaultTableModel cartModel=new DefaultTableModel(new String[]{"ID","Medicine","Price","Qty","Subtotal"},0); JTable cart=new JTable(cartModel); JLabel total=new JLabel("Total: R0.00"); Map<Integer,Integer> quantities=new HashMap<>();
    public CashierDashboard(User user){this.user=user;setTitle("HealthFirst - Cashier POS");setSize(950,600);setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);setLocationRelativeTo(null);add(header(),BorderLayout.NORTH);add(pos(),BorderLayout.CENTER);}
    JPanel header(){JPanel p=new JPanel(new BorderLayout());p.add(new JLabel("  Cashier: "+user.fullName),BorderLayout.WEST);JButton l=new JButton("Logout");p.add(l,BorderLayout.EAST);l.addActionListener(e->{dispose();new Login().setVisible(true);});return p;}
    JPanel pos(){JPanel p=new JPanel(new BorderLayout());JPanel top=new JPanel();JTextField search=new JTextField(20);JButton check=new JButton("Check Stock");JButton add=new JButton("Add to Cart");top.add(new JLabel("Medicine ID:"));top.add(search);top.add(check);top.add(add);p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(cart),BorderLayout.CENTER);JPanel bottom=new JPanel();JButton checkout=new JButton("Checkout / Bill"),clear=new JButton("Clear Cart");bottom.add(total);bottom.add(clear);bottom.add(checkout);p.add(bottom,BorderLayout.SOUTH);
        check.addActionListener(e->stock(search.getText()));add.addActionListener(e->addItem(search.getText()));clear.addActionListener(e->{cartModel.setRowCount(0);quantities.clear();updateTotal();});checkout.addActionListener(e->checkout());return p;}
    void stock(String id){try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("SELECT name,price,quantity_in_stock FROM medicines WHERE medicine_id=?")){p.setInt(1,Integer.parseInt(id));ResultSet r=p.executeQuery();if(r.next())JOptionPane.showMessageDialog(this,r.getString(1)+"\nPrice: R"+r.getDouble(2)+"\nAvailable: "+r.getInt(3));else JOptionPane.showMessageDialog(this,"Medicine not found.");}catch(Exception e){JOptionPane.showMessageDialog(this,"Enter a valid medicine ID.");}}
    void addItem(String id){try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("SELECT name,price,quantity_in_stock FROM medicines WHERE medicine_id=?")){p.setInt(1,Integer.parseInt(id));ResultSet r=p.executeQuery();if(!r.next()){JOptionPane.showMessageDialog(this,"Medicine not found.");return;}int med=Integer.parseInt(id),qty=quantities.getOrDefault(med,0)+1;if(qty>r.getInt(3)){JOptionPane.showMessageDialog(this,"Not enough stock.");return;}quantities.put(med,qty);boolean found=false;for(int i=0;i<cartModel.getRowCount();i++)if((int)cartModel.getValueAt(i,0)==med){cartModel.setValueAt(qty,i,3);cartModel.setValueAt(qty*r.getDouble(2),i,4);found=true;}if(!found)cartModel.addRow(new Object[]{med,r.getString(1),r.getDouble(2),qty,qty*r.getDouble(2)});updateTotal();}catch(Exception e){JOptionPane.showMessageDialog(this,"Enter a valid medicine ID.");}}
    void updateTotal(){double x=0;for(int i=0;i<cartModel.getRowCount();i++)x+=(double)cartModel.getValueAt(i,4);total.setText(String.format("Total: R%.2f",x));}
    void checkout(){if(cartModel.getRowCount()==0){JOptionPane.showMessageDialog(this,"Cart is empty.");return;}try(Connection c=DB.getConnection()){c.setAutoCommit(false);double totalAmount=0;for(int i=0;i<cartModel.getRowCount();i++)totalAmount+=(double)cartModel.getValueAt(i,4);PreparedStatement s=c.prepareStatement("INSERT INTO sales(total_amount,user_id) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS);s.setDouble(1,totalAmount);s.setInt(2,user.id);s.executeUpdate();ResultSet keys=s.getGeneratedKeys();keys.next();int saleId=keys.getInt(1);PreparedStatement item=c.prepareStatement("INSERT INTO sale_items(sale_id,medicine_id,quantity_sold,price_at_sale) VALUES(?,?,?,?)");PreparedStatement stock=c.prepareStatement("UPDATE medicines SET quantity_in_stock=quantity_in_stock-? WHERE medicine_id=?");for(int i=0;i<cartModel.getRowCount();i++){int med=(int)cartModel.getValueAt(i,0),qty=(int)cartModel.getValueAt(i,3);double price=(double)cartModel.getValueAt(i,2);item.setInt(1,saleId);item.setInt(2,med);item.setInt(3,qty);item.setDouble(4,price);item.executeUpdate();stock.setInt(1,qty);stock.setInt(2,med);stock.executeUpdate();}c.commit();bill(saleId,totalAmount);cartModel.setRowCount(0);quantities.clear();updateTotal();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}
    void bill(int saleId,double totalAmount){StringBuilder b=new StringBuilder("HEALTHFIRST PHARMACY\nSale #: "+saleId+"\n-----------------------------\n");for(int i=0;i<cartModel.getRowCount();i++)b.append(cartModel.getValueAt(i,1)+" x"+cartModel.getValueAt(i,3)+" = R"+cartModel.getValueAt(i,4)+"\n");b.append("-----------------------------\nTOTAL: R").append(String.format("%.2f",totalAmount));JTextArea a=new JTextArea(b.toString());a.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(a),"Customer Bill",JOptionPane.INFORMATION_MESSAGE);}
}
